if (path === '/order') {
  const o = ORDERS[q.id];
  if (!o) return html('<h1>Commande introuvable</h1>');
  const cookieHdr = headers.cookie || '';
  if (/session=admin-7c9e/.test(cookieHdr)) return html(page('order.html').replace('<!--ORDER-->', `<p><b>Commande ${esc(q.id)}</b></p><p>${esc(o.customer)} · ${esc(o.email)}<br>${esc(o.address)}<br>Total ${o.total} € · carte ${o.card}</p>`));
  const m = cookieHdr.match(/(?:^|;\s*)customer=([^;]*)/);
  let cust = '';
  try { cust = decodeURIComponent((m && m[1] || '').trim()); } catch { cust = (m && m[1] || '').trim(); }
  if (!cust || cust !== o.email) return [403, { 'content-type': 'text/html; charset=utf-8' }, '<h1>Accès refusé</h1>'];
  return html(page('order.html').replace('<!--ORDER-->', `<p><b>Commande ${esc(q.id)}</b></p><p>${esc(o.customer)} · ${esc(o.email)}<br>${esc(o.address)}<br>Total ${o.total} € · carte ${o.card}</p>`));
}

